75	fn extract_text(content: &Content) -> Option<String> {
76	    match content {
77	        Content::Text(s) => Some(s.clone()),
78	        Content::Blocks(blocks) => {
79	            let texts: Vec<&str> = blocks
80	                .iter()
81	                .filter(|b| b.block_type == "text")
82	                .filter_map(|b| b.text.as_deref())
83	                .collect();
84	            if texts.is_empty() {
85	                None
86	            } else {
87	                Some(texts.join("\n"))
88	            }
89	        }
90	    }
91	}
