160	fn parse_session_content(content: &str) -> (SessionInfo, Vec<Chunk>) {
161	    let mut chunks = Vec::new();
162	    let mut info = SessionInfo { custom_title: None, cwd: None };
163	    let mut offset: u64 = 0;
164	
165	    for line in content.lines() {
166	        let line_offset = offset;
167	        offset += line.len() as u64 + 1;
168	
169	        if line.trim().is_empty() {
170	            continue;
171	        }
172	
173	        let entry: SessionEntry = match serde_json::from_str(line) {
174	            Ok(e) => e,
175	            Err(_) => continue,
176	        };
177	
178	        if entry.entry_type == "custom-title" {
179	            if let Some(ref title) = entry.custom_title {
180	                info.custom_title = Some(title.clone());
181	            }
182	            continue;
183	        }
184	
185	        if info.cwd.is_none() {
186	            if let Some(ref cwd) = entry.cwd {
187	                info.cwd = Some(cwd.clone());
188	            }
189	        }
190	
191	        if entry.entry_type != "user" && entry.entry_type != "assistant" {
192	            continue;
193	        }
194	
195	        let msg = match &entry.message {
196	            Some(m) => m,
197	            None => continue,
198	        };
199	
200	        let role = match &msg.role {
201	            Some(r) if r == "user" || r == "assistant" => r.clone(),
202	            _ => continue,
203	        };
204	
205	        let content_field = match &msg.content {
206	            Some(c) => c,
207	            None => continue,
208	        };
209	
210	        let raw_text = match extract_text(content_field) {
211	            Some(t) => t,
212	            None => continue,
213	        };
214	
215	        let text = sanitize(&raw_text);
216	        if text.is_empty() {
217	            continue;
218	        }
219	
220	        // "[Image: source: /path]" is a synthetic label Claude Code emits for
221	        // image attachments — it's not searchable content and produces spurious
222	        // vector-search hits. Skip the whole chunk if that's all it is.
223	        if text.trim_start().starts_with("[Image:") || text.trim_start().starts_with("[image:") {
224	            continue;
225	        }
226	
227	        if !(MIN_CHUNK_CODEPOINTS..=MAX_CHUNK_CODEPOINTS).contains(&codepoint_len(&text)) {
228	            continue;
229	        }
230	
231	        let timestamp = match &entry.timestamp {
232	            Some(ts) if !ts.is_empty() => ts.clone(),
233	            _ => continue,
234	        };
235	
236	        let ts_ms = chrono::DateTime::parse_from_rfc3339(&timestamp)
237	            .map(|dt| dt.timestamp_millis())
238	            .unwrap_or(0);
239	
240	        if ts_ms <= 0 {
241	            continue;
242	        }
243	
244	        chunks.push(Chunk {
245	            role,
246	            text,
247	            timestamp,
248	            msg_uuid: entry.uuid,
249	            ts_ms,
250	            byte_offset: line_offset,
251	            byte_len: line.len() as u64,
252	            git_branch: entry.git_branch,
253	        });
254	    }
255	
256	    chunks.sort_by_key(|c| c.ts_ms);
257	    (info, chunks)
258	}
