382	/// Index commit messages from the `checkpoints` table for all sessions
383	/// belonging to `repo_dir`. Called unconditionally on every ingest so that
384	/// commit messages stay current even when the checkpoint-branch HEAD hasn't
385	/// moved. `add_doc` is an upsert keyed on a stable UUID, so re-running is safe.
386	fn index_checkpoint_commits(
387	    db: &mut DB,
388	    conn: &rusqlite::Connection,
389	    repo_dir: &str,
390	) -> Result<()> {
391	    let mut stmt = conn.prepare(
392	        "SELECT c.checkpoint_id, c.commit_message, c.last_turn_ts,
393	                s.session_id, COALESCE(s.session_name,''), COALESCE(s.cwd,'')
394	         FROM checkpoints c
395	         JOIN sessions s ON s.session_id = c.session_id
396	         WHERE (
397	             s.repo_id = (SELECT id FROM repositories WHERE directory = ?1)
398	             OR (s.repo_id IS NULL AND s.cwd LIKE ?2)
399	         )
400	         AND c.commit_message IS NOT NULL
401	         AND c.commit_message != ''"
402	    )?;
403	
404	    let pattern = format!("{}%", repo_dir);
405	    let rows: Vec<(String, String, String, String, String, String)> = stmt
406	        .query_map(rusqlite::params![repo_dir, pattern], |row| {
407	            Ok((
408	                row.get::<_, String>(0)?,
409	                row.get::<_, String>(1)?,
410	                row.get::<_, String>(2)?,
411	                row.get::<_, String>(3)?,
412	                row.get::<_, String>(4)?,
413	                row.get::<_, String>(5)?,
414	            ))
415	        })?
416	        .filter_map(|r| r.ok())
417	        .collect();
418	
419	    for (checkpoint_id, message, ts, session_id, session_name, cwd) in &rows {
420	        let project_name = if cwd.is_empty() {
421	            session_id.chars().take(8).collect::<String>()
422	        } else {
423	            cwd.trim_start_matches('/').to_string()
424	        };
425	        let body = format!("[{project_name}] {session_name}\n[Checkpoint] {message}\n");
426	        let uuid = Uuid::new_v5(
427	            &CLAUDE_CODE_NAMESPACE,
428	            format!("{session_id}:cp:{checkpoint_id}").as_bytes(),
429	        );
430	        let metadata = serde_json::json!({
431	            "source": "checkpoint",
432	            "project": project_name,
433	            "session_id": session_id,
434	            "session_name": session_name,
435	            "checkpoint_id": checkpoint_id,
436	        }).to_string();
437	        let date = iso8601_timestamp::Timestamp::parse(ts);
438	        db.add_doc(&uuid, date, &metadata, &body, None)?;
439	    }
440	    Ok(())
441	}
