443	fn ingest_repo(
444	    db: &mut DB,
445	    conn: &rusqlite::Connection,
446	    repo_dir: &str,
447	) -> Result<usize> {
448	    let head_out = Command::new("git")
449	        .args(["rev-parse", BRANCH])
450	        .current_dir(repo_dir)
451	        .output()?;
452	
453	    if !head_out.status.success() {
454	        return Ok(0);
455	    }
456	    let current_head = String::from_utf8_lossy(&head_out.stdout).trim().to_string();
457	
458	    let stored_head: Option<String> = conn.query_row(
459	        "SELECT last_search_commit FROM repositories WHERE directory = ?1",
460	        [repo_dir],
461	        |row| row.get(0),
462	    ).ok().flatten();
463	
464	    // Always refresh commit messages regardless of JSONL watermark state.
465	    if let Err(e) = index_checkpoint_commits(db, conn, repo_dir) {
466	        eprintln!("  warning: failed to index checkpoint commits for {repo_dir}: {e}");
467	    }
468	
469	    if stored_head.as_deref() == Some(current_head.as_str()) {
470	        return Ok(0);
471	    }
472	
473	    // Find meta paths changed since last search index run
474	    let meta_paths: Vec<String> = if let Some(ref last) = stored_head {
475	        let out = Command::new("git")
476	            .args(["diff", "--name-only", "--diff-filter=AM", last, BRANCH])
477	            .current_dir(repo_dir)
478	            .output()?;
479	        String::from_utf8(out.stdout)?
480	            .lines()
481	            .filter(|l| is_meta_path(l))
482	            .map(str::to_string)
483	            .collect()
484	    } else {
485	        let out = Command::new("git")
486	            .args(["ls-tree", "-r", "--name-only", BRANCH])
487	            .current_dir(repo_dir)
488	            .output()?;
489	        String::from_utf8(out.stdout)?
490	            .lines()
491	            .filter(|l| is_meta_path(l))
492	            .map(str::to_string)
493	            .collect()
494	    };
495	
496	    // Deduplicate: keep only the latest checkpoint per session (highest num in path)
497	    // Path: <prefix2>/<id10>/<num>/metadata.json
498	    let mut latest: std::collections::HashMap<String, (u32, String)> = std::collections::HashMap::new();
499	    for meta_path in &meta_paths {
500	        let parts: Vec<&str> = meta_path.splitn(4, '/').collect();
501	        if parts.len() != 4 { continue }
502	        let checkpoint_key = format!("{}/{}", parts[0], parts[1]);
503	        let num: u32 = parts[2].parse().unwrap_or(0);
504	        let entry = latest.entry(checkpoint_key).or_insert((0, meta_path.clone()));
505	        if num >= entry.0 {
506	            *entry = (num, meta_path.clone());
507	        }
508	    }
509	
510	    let mut count = 0usize;
511	
512	    for (_key, (_num, meta_path)) in &latest {
513	        let jsonl_path = format!(
514	            "{}full.jsonl",
515	            &meta_path[..meta_path.len() - "metadata.json".len()]
516	        );
517	
518	        let meta_bytes = match git_show(repo_dir, meta_path) {
519	            Ok(b) => b,
520	            Err(e) => { eprintln!("  skipping {meta_path}: {e}"); continue }
521	        };
522	        let jsonl_bytes = match git_show(repo_dir, &jsonl_path) {
523	            Ok(b) => b,
524	            Err(_) => continue,
525	        };
526	
527	        let meta: serde_json::Value = match serde_json::from_slice(&meta_bytes) {
528	            Ok(v) => v,
529	            Err(_) => continue,
530	        };
531	        let session_id = match meta["session_id"].as_str() {
532	            Some(s) => s.to_string(),
533	            None => continue,
534	        };
535	
536	        let content = String::from_utf8_lossy(&jsonl_bytes);
537	
538	        match ingest_session(db, &session_id, &content, "") {
539	            Ok((n, custom_title)) => {
540	                count += n;
541	                if let Some(title) = custom_title {
542	                    let _ = conn.execute(
543	                        "UPDATE sessions SET session_name = ?1 WHERE session_id = ?2",
544	                        rusqlite::params![title, session_id.as_str()],
545	                    );
546	                }
547	            }
548	            Err(e) => eprintln!("  warning: failed to ingest {session_id}: {e}"),
549	        }
550	    }
551	
552	    conn.execute(
553	        "UPDATE repositories SET last_search_commit = ?1 WHERE directory = ?2",
554	        rusqlite::params![current_head, repo_dir],
555	    )?;
556	
557	    Ok(count)
558	}
