37	pub fn ingest_sessions(wc_db: &mut witchcraft::DB) -> Result<usize> {
38	    let conn = crate::db::connect()?;
39	    let mut stmt = conn.prepare(
40	        "SELECT session_id, session_name, cwd, agent_name, updated_at FROM sessions",
41	    )?;
42	
43	    let rows: Vec<(String, String, String, String, String)> = stmt
44	        .query_map([], |row| {
45	            Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?))
46	        })?
47	        .flatten()
48	        .collect();
49	
50	    let mut count = 0;
51	    for (session_id, session_name, cwd, agent_name, updated_at) in rows {
52	        let name = session_name.trim().to_string();
53	        if name.is_empty() {
54	            continue;
55	        }
56	
57	        let uuid = Uuid::new_v5(&SESSION_NAMESPACE, session_id.as_bytes());
58	        let metadata = serde_json::json!({
59	            "source": "session",
60	            "session_id": session_id,
61	            "session_name": name,
62	            "cwd": cwd,
63	            "agent_name": agent_name,
64	        })
65	        .to_string();
66	
67	        let body = format!("{name}\n{cwd}\n{agent_name}");
68	        let date = iso8601_timestamp::Timestamp::parse(&updated_at);
