76	/// Scan live JSONL files in ~/.claude/projects/ and backfill session_name for
77	/// any sessions in the DB whose name is currently blank.
78	pub fn backfill_session_names() -> Result<usize> {
79	    let home = std::env::var("HOME").context("HOME not set")?;
80	    let projects_dir = std::path::PathBuf::from(&home).join(".claude/projects");
81	
82	    let conn = crate::db::connect()?;
83	
84	    // Collect session IDs that need a name.
85	    let mut stmt = conn.prepare(
86	        "SELECT session_id FROM sessions WHERE session_name = '' OR session_name IS NULL",
87	    )?;
88	    let nameless: std::collections::HashSet<String> = stmt
89	        .query_map([], |row| row.get::<_, String>(0))?
90	        .flatten()
91	        .collect();
92	
93	    if nameless.is_empty() {
94	        return Ok(0);
95	    }
96	
97	    let mut updated = 0usize;
98	
99	    let Ok(project_dirs) = std::fs::read_dir(&projects_dir) else { return Ok(0) };
100	    for project in project_dirs.flatten() {
101	        let Ok(files) = std::fs::read_dir(project.path()) else { continue };
102	        for file in files.flatten() {
103	            let path = file.path();
104	            if path.extension().and_then(|e| e.to_str()) != Some("jsonl") { continue }
105	            let session_id = match path.file_stem().and_then(|s| s.to_str()) {
106	                Some(s) => s.to_string(),
107	                None => continue,
108	            };
109	            if !nameless.contains(&session_id) { continue }
110	
111	            let Ok(f) = std::fs::File::open(&path) else { continue };
112	            let reader = std::io::BufReader::new(f);
113	            let mut custom_title: Option<String> = None;
114	            for line in std::io::BufRead::lines(reader).flatten() {
115	                if let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) {
116	                    if v["type"].as_str() == Some("custom-title") {
117	                        if let Some(t) = v["customTitle"].as_str() {
118	                            custom_title = Some(t.to_string());
119	                            break;
120	                        }
121	                    }
122	                }
123	            }
124	            let Some(title) = custom_title else { continue };
125	            conn.execute(
126	                "UPDATE sessions SET session_name = ?1 WHERE session_id = ?2",
127	                rusqlite::params![title, session_id],
128	            )?;
129	            updated += 1;
130	        }
131	    }
132	
133	    Ok(updated)
134	}
