10	pub fn run(json: bool) -> Result<()> {
11	    let conn = db::connect()?;
12	
13	    let mut stmt = conn.prepare("SELECT id, directory, name FROM repositories")?;
14	    let repos: Vec<(i64, String, String)> = stmt
15	        .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
16	        .collect::<Result<_, _>>()?;
17	
18	    if repos.is_empty() {
19	        if json {
20	            println!("{}", serde_json::json!({"sessions_indexed": 0}));
21	        } else {
22	            println!("No repositories tracked. Run `entire gossamer init` first.");
23	        }
24	        return Ok(());
25	    }
26	
27	    let resolver = RepoResolver::new(&conn)?;
28	
29	    let mut grand_total = 0usize;
30	
31	    for (repo_id, dir, name) in &repos {
32	        match refresh_repo(&conn, *repo_id, dir, &resolver) {
33	            Ok(0) => { if !json { println!("'{}': up to date.", name); } }
34	            Ok(n) => {
35	                if !json { println!("'{}': {} new session(s) indexed.", name, n); }
36	                grand_total += n;
37	            }
38	            Err(e) => eprintln!("'{}': error — {}", name, e),
39	        }
40	    }
41	
42	    let names_filled = crate::ingest::backfill_session_names().unwrap_or(0);
43	
44	    if json {
45	        println!("{}", serde_json::to_string_pretty(&serde_json::json!({
46	            "sessions_indexed": grand_total,
47	            "names_backfilled": names_filled,
48	        }))?);
49	    } else {
50	        println!();
51	        if grand_total > 0 {
52	            println!("{} new session(s) indexed.", grand_total);
53	        } else {
54	            println!("All repositories up to date.");
55	        }
56	        if names_filled > 0 {
57	            println!("{} session name(s) backfilled.", names_filled);
58	        }
