64	fn refresh_repo(conn: &rusqlite::Connection, repo_id: i64, repo_dir: &str, resolver: &RepoResolver) -> Result<usize> {
65	    fetch_checkpoint_branch(repo_dir);
66	
67	    // Shadow branches advance on every prompt, so we always sweep them — even
68	    // when the checkpoint head is unchanged, an active session can have new
69	    // turns visible only on its shadow ref.
70	    let shadow_count = index_shadow_branches(conn, repo_id, repo_dir, resolver).unwrap_or(0);
71	
72	    // Check checkpoint branch exists.
73	    let check = Command::new("git")
74	        .args(["rev-parse", "--verify", BRANCH])
75	        .current_dir(repo_dir)
76	        .output()?;
77	
78	    if !check.status.success() {
79	        return Ok(shadow_count);
80	    }
81	
82	    let current_head = String::from_utf8(check.stdout)?.trim().to_string();
83	
84	    // Load stored watermark.
85	    let stored_head: Option<String> = conn.query_row(
86	        "SELECT last_indexed_commit FROM repositories WHERE directory = ?1",
87	        [repo_dir],
88	        |row| row.get(0),
89	    ).ok().flatten();
90	
91	    if stored_head.as_deref() == Some(current_head.as_str()) {
92	        return Ok(shadow_count); // checkpoint unchanged; shadow may still have new turns
93	    }
94	
95	    // Collect metadata paths: added or modified since watermark (or all if first run).
96	    let meta_paths: Vec<String> = if let Some(ref last) = stored_head {
97	        // git diff gives a deduplicated file list between two tree states, so each
98	        // session appears at most once even if it was checkpointed many times.
99	        let out = Command::new("git")
100	            .args(["diff", "--name-only", "--diff-filter=AM", last, BRANCH])
101	            .current_dir(repo_dir)
102	            .output()?;
103	        String::from_utf8(out.stdout)?
104	            .lines()
105	            .filter(|l| is_meta_path(l))
106	            .map(str::to_string)
107	            .collect()
108	    } else {
109	        let out = Command::new("git")
110	            .args(["ls-tree", "-r", "--name-only", BRANCH])
111	            .current_dir(repo_dir)
112	            .output()?;
113	        String::from_utf8(out.stdout)?
114	            .lines()
115	            .filter(|l| is_meta_path(l))
116	            .map(str::to_string)
117	            .collect()
118	    };
119	
120	    let user = std::env::var("USER")
121	        .or_else(|_| std::env::var("USERNAME"))
122	        .unwrap_or_else(|_| "unknown".to_string());
123	
124	    let mut count = 0;
125	    for meta_path in &meta_paths {
126	        let jsonl_path = format!(
127	            "{}full.jsonl",
128	            &meta_path[..meta_path.len() - "metadata.json".len()]
129	        );
130	        let meta_bytes = match git_show(repo_dir, meta_path) {
131	            Ok(b) => b,
132	            Err(e) => { eprintln!("  skipping {}: {}", meta_path, e); continue; }
133	        };
134	        let jsonl_bytes = match git_show(repo_dir, &jsonl_path) {
135	            Ok(b) => b,
136	            Err(_) => continue,
137	        };
138	        match crate::parsers::dispatch_session(&meta_bytes, &jsonl_bytes) {
139	            Ok(p) => {
140	                let resolved_id = resolver.resolve(&p.cwd, Some(repo_id));
141	                upsert_session(conn, &p.session_id, &p.agent_name, &user,
142	                               &p.created_at, &p.updated_at, &p.cwd, &p.session_name,
143	                               &p.branch, resolved_id, p.name_is_explicit, p.tokens_used)?;
144	                count += 1;
145	            }
146	            Err(e) => eprintln!("  skipping {}: {}", meta_path, e),
147	        }
148	    }
149	
150	    // Advance watermark.
151	    conn.execute(
152	        "UPDATE repositories SET last_indexed_commit = ?1 WHERE directory = ?2",
153	        rusqlite::params![current_head, repo_dir],
154	    )?;
155	
156	    Ok(count + shadow_count)
157	}
