1	//! Claude Code JSONL pipeline. Each line is a top-level
2	//! `{"type": "user"|"assistant"|"system"|"custom-title", ...}` event.
3	//! User/assistant turns carry their content in `message.content`, which can
4	//! be either a plain string or an array of `{"type": "text"|"tool_use"|..., ...}`
5	//! blocks. cwd and gitBranch are stamped onto each user/system entry.
6	
7	use anyhow::{Context, Result};
8	use chrono::{DateTime, Utc};
9	use serde::Deserialize;
10	use serde_json::Value;
11	
12	use super::ParsedSession;
13	
14	pub fn parse_session(meta_bytes: &[u8], jsonl_bytes: &[u8]) -> Result<ParsedSession> {
15	    #[derive(Deserialize)]
16	    struct SessionMetadata {
17	        session_id: String,
18	        agent: Option<String>,
19	        created_at: Option<String>,
20	        branch: Option<String>,
21	        summary: Option<Summary>,
22	        token_usage: Option<TokenUsage>,
23	    }
24	    #[derive(Deserialize)]
25	    struct Summary {
26	        intent: Option<String>,
27	    }
28	    #[derive(Deserialize)]
29	    struct TokenUsage {
30	        output_tokens: Option<i64>,
31	    }
32	
33	    let meta: SessionMetadata = serde_json::from_slice(meta_bytes)
34	        .context("failed to parse metadata.json")?;
35	
36	    let created_at: DateTime<Utc> = meta
37	        .created_at
38	        .as_deref()
39	        .and_then(|s| DateTime::parse_from_rfc3339(s).ok())
40	        .map(|dt| dt.with_timezone(&Utc))
41	        .unwrap_or_else(Utc::now);
42	
43	    let metadata_intent = meta
44	        .summary
45	        .and_then(|s| s.intent)
46	        .filter(|s| !s.is_empty())
47	        .unwrap_or_else(|| format!("session:{}", &meta.session_id[..8]));
48	
49	    let agent_name = meta.agent.unwrap_or_else(|| "Claude Code".to_string());
50	    let meta_branch = meta.branch.unwrap_or_default();
51	
52	    let tokens_used = meta.token_usage
53	        .and_then(|u| u.output_tokens)
54	        .unwrap_or(0);
55	
56	    let mut latest: Option<DateTime<Utc>> = None;
57	    let mut cwd = String::new();
58	    let mut first_meaningful_prompt: Option<String> = None;
59	    let mut first_any_prompt: Option<String> = None;
60	    let mut custom_title: Option<String> = None;
61	    let mut jsonl_branch = String::new();
62	
63	    for line in jsonl_bytes.split(|&b| b == b'\n') {
64	        if line.is_empty() { continue; }
65	        let v: Value = match serde_json::from_slice(line) {
66	            Ok(v) => v,
67	            Err(_) => continue,
68	        };
69	
70	        if let Some(ts) = v.get("timestamp").and_then(Value::as_str) {
71	            if let Ok(dt) = DateTime::parse_from_rfc3339(ts) {
72	                let dt: DateTime<Utc> = dt.with_timezone(&Utc);
73	                if latest.map_or(true, |l| dt > l) { latest = Some(dt); }
74	            }
75	        }
76	
77	        if cwd.is_empty() {
78	            if let Some(c) = v.get("cwd").and_then(Value::as_str) { cwd = c.to_string(); }
79	        }
80	
81	        if let Some(b) = v.get("gitBranch").and_then(Value::as_str) {
82	            if !b.is_empty() { jsonl_branch = b.to_string(); }
83	        }
84	
85	        match v.get("type").and_then(Value::as_str) {
86	            Some("custom-title") => {
87	                if let Some(t) = v.get("customTitle").and_then(Value::as_str) {
88	                    if !t.trim().is_empty() { custom_title = Some(t.trim().to_string()); }
89	                }
90	            }
91	            Some("user") => {
92	                if let Some(text) = extract_user_text(&v["message"]["content"]) {
93	                    if first_any_prompt.is_none() { first_any_prompt = Some(text.clone()); }
94	                    if first_meaningful_prompt.is_none() && !is_wrapper_prompt(&text) {
95	                        first_meaningful_prompt = Some(text);
96	                    }
97	                }
98	            }
99	            _ => {}
100	        }
101	    }
102	
103	    let updated_at = latest.unwrap_or(created_at);
104	    let name_is_explicit = custom_title.is_some();
105	    let session_name = custom_title
106	        .or(first_meaningful_prompt)
107	        .or(first_any_prompt)
108	        .unwrap_or(metadata_intent);
109	    let session_name = crate::commands::session_list::sanitize_one_line(&session_name);
110	    let branch = if !jsonl_branch.is_empty() { jsonl_branch } else { meta_branch };
111	
112	    Ok(ParsedSession {
113	        session_id: meta.session_id,
114	        agent_name,
115	        created_at: created_at.to_rfc3339(),
116	        updated_at: updated_at.to_rfc3339(),
117	        cwd,
118	        session_name,
119	        branch,
120	        name_is_explicit,
121	        tokens_used,
122	    })
123	}
