125	pub fn parse_shadow_session(jsonl_bytes: &[u8], session_id: &str) -> Result<ParsedSession> {
126	    let mut earliest: Option<DateTime<Utc>> = None;
127	    let mut latest: Option<DateTime<Utc>> = None;
128	    let mut cwd = String::new();
129	    let mut first_meaningful_prompt: Option<String> = None;
130	    let mut first_any_prompt: Option<String> = None;
131	    let mut custom_title: Option<String> = None;
132	    let mut branch = String::new();
133	    let mut tokens_used: i64 = 0;
134	
135	    for line in jsonl_bytes.split(|&b| b == b'\n') {
136	        if line.is_empty() { continue; }
137	        let v: Value = match serde_json::from_slice(line) {
138	            Ok(v) => v,
139	            Err(_) => continue,
140	        };
141	
142	        if let Some(ts) = v.get("timestamp").and_then(Value::as_str) {
143	            if let Ok(dt) = DateTime::parse_from_rfc3339(ts) {
144	                let dt: DateTime<Utc> = dt.with_timezone(&Utc);
145	                if earliest.map_or(true, |e| dt < e) { earliest = Some(dt); }
146	                if latest.map_or(true, |l| dt > l)   { latest   = Some(dt); }
147	            }
148	        }
149	
150	        if cwd.is_empty() {
151	            if let Some(c) = v.get("cwd").and_then(Value::as_str) { cwd = c.to_string(); }
152	        }
153	
154	        if let Some(b) = v.get("gitBranch").and_then(Value::as_str) {
155	            if !b.is_empty() { branch = b.to_string(); }
156	        }
157	
158	        match v.get("type").and_then(Value::as_str) {
159	            Some("custom-title") => {
160	                if let Some(t) = v.get("customTitle").and_then(Value::as_str) {
161	                    if !t.trim().is_empty() { custom_title = Some(t.trim().to_string()); }
162	                }
163	            }
164	            Some("user") => {
165	                if let Some(text) = extract_user_text(&v["message"]["content"]) {
166	                    if first_any_prompt.is_none() { first_any_prompt = Some(text.clone()); }
167	                    if first_meaningful_prompt.is_none() && !is_wrapper_prompt(&text) {
168	                        first_meaningful_prompt = Some(text);
169	                    }
170	                }
171	            }
172	            Some("assistant") => {
173	                if let Some(n) = v["message"]["usage"]["output_tokens"].as_i64() {
174	                    tokens_used += n;
175	                }
176	            }
177	            _ => {}
178	        }
179	    }
180	
181	    let created_at = earliest.unwrap_or_else(Utc::now);
182	    let updated_at = latest.unwrap_or(created_at);
183	    let name_is_explicit = custom_title.is_some();
184	    let session_name = custom_title
185	        .or(first_meaningful_prompt)
186	        .or(first_any_prompt)
187	        .unwrap_or_else(|| format!("session:{}", &session_id[..session_id.len().min(8)]));
188	    let session_name = crate::commands::session_list::sanitize_one_line(&session_name);
189	
190	    Ok(ParsedSession {
191	        session_id: session_id.to_string(),
192	        agent_name: "Claude Code".to_string(),
193	        created_at: created_at.to_rfc3339(),
194	        updated_at: updated_at.to_rfc3339(),
195	        cwd,
196	        session_name,
197	        branch,
198	        name_is_explicit,
199	        tokens_used,
200	    })
201	}
