203	/// Pull a user message's text out of either the string or block-array shape
204	/// that Claude Code uses. Trims and returns None for empty content.
205	fn extract_user_text(content: &Value) -> Option<String> {
206	    match content {
207	        Value::String(s) => {
208	            let t = s.trim();
209	            if t.is_empty() { None } else { Some(t.to_string()) }
210	        }
211	        Value::Array(blocks) => {
212	            let texts: Vec<&str> = blocks.iter()
213	                .filter(|b| b.get("type").and_then(Value::as_str) == Some("text"))
214	                .filter_map(|b| b.get("text").and_then(Value::as_str))
