134	fn strip_code(text: &str) -> String {
135	    let re = Regex::new(r"```[\s\S]*?```").unwrap();
136	    let s = re.replace_all(text, " ").to_string();
137	    let re = Regex::new(r"```[\s\S]*$").unwrap();
138	    let s = re.replace_all(&s, " ").to_string();
139	    // Strip the backticks but keep the inner text so words like `index` stay
140	    // readable in search excerpts rather than turning into blank spaces.
141	    let re = Regex::new(r"`([^`]*)`").unwrap();
142	    re.replace_all(&s, "$1").to_string()
143	}
