160	fn parse_session_content(content: &str) -> (SessionInfo, Vec<Chunk>) {
161	    let mut chunks = Vec::new();
162	    let mut info = SessionInfo { custom_title: None, cwd: None };
163	    let mut offset: u64 = 0;
164	
165	    for line in content.lines() {
166	        let line_offset = offset;
167	        offset += line.len() as u64 + 1;
168	
169	        if line.trim().is_empty() {
170	            continue;
171	        }
172	
173	        let entry: SessionEntry = match serde_json::from_str(line) {
174	            Ok(e) => e,
175	            Err(_) => continue,
176	        };
177	
178	        if entry.entry_type == "custom-title" {
179	            if let Some(ref title) = entry.custom_title {
180	                info.custom_title = Some(title.clone());
181	            }
182	            continue;
183	        }
184	
185	        if info.cwd.is_none() {
186	            if let Some(ref cwd) = entry.cwd {
187	                info.cwd = Some(cwd.clone());
188	            }
189	        }
190	
191	        if entry.entry_type != "user" && entry.entry_type != "assistant" {
192	            continue;
193	        }
194	
195	        let msg = match &entry.message {
196	            Some(m) => m,
197	            None => continue,
198	        };
199	
200	        let role = match &msg.role {
201	            Some(r) if r == "user" || r == "assistant" => r.clone(),
202	            _ => continue,
203	        };
204	
205	        let content_field = match &msg.content {
206	            Some(c) => c,
207	            None => continue,
208	        };
209	
210	        let raw_text = match extract_text(content_field) {
211	            Some(t) => t,
212	            None => continue,
