244	        chunks.push(Chunk {
245	            role,
246	            text,
247	            timestamp,
248	            msg_uuid: entry.uuid,
249	            ts_ms,
250	            byte_offset: line_offset,
251	            byte_len: line.len() as u64,
252	            git_branch: entry.git_branch,
253	        });
254	    }
255	
256	    chunks.sort_by_key(|c| c.ts_ms);
257	    (info, chunks)
258	}
