94	/// Open a session and jump to a specific turn or checkpoint.
95	/// `turn_id`      — JSONL message uuid (stable across file versions).
96	/// `hit_ts`       — raw timestamp string fallback.
97	/// `hit_off`      — byte offset of the matched JSONL line (most reliable; bypasses string matching).
98	/// `checkpoint_id`— navigate directly to the matching Checkpoint card.
99	pub fn run_at(session_id: &str, turn_id: Option<&str>, hit_ts: Option<&str>, hit_off: Option<u64>, checkpoint_id: Option<&str>) -> Result<bool> {
100	    let path = find_session(session_id)
101	        .with_context(|| format!("no session file found for '{session_id}'"))?;
102	
103	    let raw = std::fs::read_to_string(&path)
104	        .with_context(|| format!("cannot read {}", path.display()))?;
105	
106	
107	    // Resolve to a timestamp for pager navigation.
108	    // Priority: raw hit_ts (directly from witchcraft metadata, same source as
109	    // the JSONL timestamp field) → uuid scan of local file → byte-offset scan
110	    // (hit_off is relative to the shadow-branch copy, so only use as a last
111	    // resort when the other two come up empty).
112	    let resolved_ts: Option<String> = hit_ts.map(str::to_string)
113	        .or_else(|| turn_id.and_then(|tid| {
114	            for line in raw.lines() {
115	                let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else { continue };
116	                if v["uuid"].as_str() == Some(tid) {
117	                    return v["timestamp"].as_str().map(str::to_string);
118	                }
119	            }
120	            None
121	        }))
122	        .or_else(|| hit_off.and_then(|off| {
123	            let bytes = raw.as_bytes();
124	            if (off as usize) < bytes.len() {
125	                let slice = &bytes[off as usize..];
126	                let end = slice.iter().position(|&b| b == b'\n').unwrap_or(slice.len());
127	                std::str::from_utf8(&slice[..end]).ok()
128	                    .and_then(|line| serde_json::from_str::<serde_json::Value>(line).ok())
129	                    .and_then(|v| v["timestamp"].as_str().map(str::to_string))
130	            } else { None }
131	        }));
132	    let start_ts: Option<&str> = resolved_ts.as_deref();
133	
134	    // Look up agent name and DB-stored session_name from the gossamer DB.
135	    let uuid = path.file_stem().and_then(|s| s.to_str()).unwrap_or("");
136	    let (agent, db_session_name) = if let Ok(conn) = crate::db::connect() {
137	        conn.query_row(
138	            "SELECT agent_name, COALESCE(session_name, '') FROM sessions WHERE session_id = ?1",
139	            [uuid],
