158	    let mut need_prompt_fallback = false;
159	    if let Some(Card::Header { title, .. }) = cards.iter_mut().find(|c| matches!(c, Card::Header { .. })) {
160	        if title.as_deref().map_or(true, str::is_empty) {
161	            if !db_session_name.trim().is_empty() {
162	                *title = Some(db_session_name);
163	            } else {
164	                need_prompt_fallback = true;
165	            }
166	        }
167	    }
168	    if need_prompt_fallback {
169	        let first_user_text: Option<String> = cards.iter().find_map(|c| {
170	            if let Card::UserMsg { parts, .. } = c {
171	                parts.iter().find_map(|p| {
172	                    if let UserPart::Text(t) = p {
173	                        let trimmed = t.trim();
174	                        if trimmed.is_empty() { None } else { Some(trimmed.to_string()) }
175	                    } else { None }
