178	        });
179	        if let Some(text) = first_user_text {
180	            if let Some(Card::Header { title, .. }) = cards.iter_mut().find(|c| matches!(c, Card::Header { .. })) {
181	                *title = Some(text);
182	            }
183	        }
184	    }
185	
186	    // Extract branch and cwd from the Header before cards are consumed by pager.
187	    let session_branch = cards.iter().find_map(|c| {
