211	    // Look up the repo that owns this session's cwd and prepend a RepoLink card.
212	    if let Ok(conn) = crate::db::connect() {
213	        if let Ok((repo_name, repo_dir)) = conn.query_row(
214	            "SELECT name, directory FROM repositories
