409	fn insert_checkpoints(cards: &mut Vec<Card>, checkpoints: Vec<CheckpointData>) {
410	    // Process in reverse so earlier insertions don't shift later positions.
411	    for cp in checkpoints.into_iter().rev() {
412	        // Find the last card whose timestamp is ≤ this checkpoint's last turn.
413	        let pos = cards.iter().rposition(|c| {
414	            card_ts(c).map_or(false, |ts| ts <= cp.last_turn_ts.as_str())
415	        });
416	        let mut insert_at = pos.map(|i| i + 1).unwrap_or(cards.len());
417	        // Advance past ToolRound cards and any AsstMsg cards (away summary) that
418	        // belong to the same turn — they have no timestamp or a ts ≤ last_turn_ts.
419	        while insert_at < cards.len() {
420	            match &cards[insert_at] {
421	                Card::ToolRound { .. } => { insert_at += 1; }
422	                Card::AsstMsg { ts, .. } if ts.as_str() <= cp.last_turn_ts.as_str() => { insert_at += 1; }
423	                _ => break,
424	            }
425	        }
426	        cards.insert(insert_at, Card::Checkpoint(cp));
427	    }
428	}
