434	        let projects = PathBuf::from(&home).join(".claude/projects");
435	        if let Ok(entries) = std::fs::read_dir(&projects) {
436	            for entry in entries.flatten() {
437	                let candidate = entry.path().join(format!("{id}.jsonl"));
438	                if candidate.exists() { return Some(candidate); }
439	            }
440	        }
441	    }
442	    // Fall back to extracting the latest checkpoint's full.jsonl from the
443	    // entire/checkpoints/v1 branch. Used when this session was authored on
444	    // another machine and never produced a local Claude Code log.
445	    extract_from_checkpoint(id)
446	}
