453	           AND jsonl_path IS NOT NULL
454	         ORDER BY last_turn_ts DESC
455	         LIMIT 1",
456	        [session_id],
457	        |row| row.get(0),
458	    ).ok()?;
459	
460	    // The stored `repo_dir` is whichever repo's index pass last wrote this
461	    // checkpoint row — sometimes stale (the file may since have been removed
462	    // from that repo's branch, or the same file lives in multiple repos'
463	    // shared checkpoint branch). Try the recorded repo_dir first, then fall
464	    // back to every other tracked repo. Whichever clone actually has the path
465	    // in its checkpoint branch wins.
466	    let preferred: Option<String> = conn.query_row(
467	        "SELECT repo_dir FROM checkpoints
468	         WHERE session_id = ?1 AND repo_dir IS NOT NULL
469	         ORDER BY last_turn_ts DESC LIMIT 1",
470	        [session_id], |row| row.get(0),
471	    ).ok();
472	
473	    let mut candidates: Vec<String> = Vec::new();
474	    if let Some(p) = preferred { candidates.push(p); }
475	    if let Ok(mut stmt) = conn.prepare("SELECT directory FROM repositories") {
476	        if let Ok(rows) = stmt.query_map([], |row| row.get::<_, String>(0)) {
477	            for r in rows.flatten() {
478	                if !candidates.contains(&r) { candidates.push(r); }
479	            }
480	        }
481	    }
482	
483	    let bytes = candidates.iter()
484	        .find_map(|dir| crate::commands::index::git_show(dir, &jsonl_path).ok())?;
485	
486	    let home = std::env::var("HOME").ok()?;
487	    let cache_dir = PathBuf::from(&home).join(".gossamer").join("sessions");
488	    std::fs::create_dir_all(&cache_dir).ok()?;
489	    let cache_path = cache_dir.join(format!("{session_id}.jsonl"));
490	    std::fs::write(&cache_path, &bytes).ok()?;
491	    Some(cache_path)
492	}
