494	// ── Parsing ───────────────────────────────────────────────────────────────────
495	
496	fn parse(raw: &str, agent: &str) -> Vec<Card> {
497	    let mut tool_names: HashMap<String, String> = HashMap::new();
498	    for line in raw.lines() {
499	        if let Ok(v) = serde_json::from_str::<Value>(line) {
500	            if let Some(blocks) = v["message"]["content"].as_array() {
501	                for b in blocks {
502	                    if b["type"].as_str() == Some("tool_use") {
503	                        if let (Some(id), Some(name)) = (b["id"].as_str(), b["name"].as_str()) {
504	                            tool_names.insert(id.to_string(), name.to_string());
505	                        }
506	                    }
507	                }
508	            }
509	        }
510	    }
511	
512	    let mut cards: Vec<Card> = Vec::new();
513	    let mut first_cwd    = String::new();
514	    let mut first_branch = String::new();
515	    let mut first_ts     = String::new();
516	    let mut title: Option<String> = None;
517	
518	    for line in raw.lines() {
519	        if line.trim().is_empty() { continue; }
520	        let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
521	        let ts = v["timestamp"].as_str().unwrap_or("").to_string();
522	        if first_ts.is_empty() && !ts.is_empty() { first_ts = ts.clone(); }
523	
524	        match v["type"].as_str() {
525	            Some("custom-title") => {
526	                title = v["customTitle"].as_str().map(str::to_string);
527	            }
528	            Some("system") => {
529	                if let Some(c) = v["cwd"].as_str() { if first_cwd.is_empty() { first_cwd = c.to_string(); } }
530	                let content = v["content"].as_str().unwrap_or("").to_string();
531	                if !content.is_empty() {
532	                    let subtype = v["subtype"].as_str().unwrap_or("system").replace('_', " ");
533	                    cards.push(Card::System { ts, subtype, content });
534	                }
535	            }
536	            Some("user") => {
537	                if let Some(c) = v["cwd"].as_str()       { if first_cwd.is_empty()    { first_cwd    = c.to_string(); } }
538	                if let Some(b) = v["gitBranch"].as_str() { if first_branch.is_empty() { first_branch = b.to_string(); } }
539	                let parts = parse_user(&v["message"]["content"], &tool_names);
540	                if !parts.is_empty() { cards.push(Card::UserMsg { ts, parts, author: None }); }
541	            }
542	            Some("assistant") => {
543	                let parts = parse_asst(&v["message"]["content"]);
544	                if !parts.is_empty() { cards.push(Card::AsstMsg { ts, parts }); }
545	            }
546	            _ => {}
547	        }
548	    }
549	
550	    let mut result = vec![Card::Header { title, cwd: first_cwd, branch: first_branch, ts: first_ts, agent: agent.to_string() }];
551	    result.extend(cards);
552	
553	    // Merge each pure tool-result UserMsg into the preceding AsstMsg.
554	    let mut i = 1;
555	    while i < result.len() {
556	        let is_pure_results = if let Card::UserMsg { parts, .. } = &result[i] {
557	            parts.iter().all(|p| matches!(p, UserPart::ToolResult { .. }))
558	        } else { false };
559	
560	        if is_pure_results && matches!(&result[i - 1], Card::AsstMsg { .. }) {
561	            let tool_results: Vec<(String, String, bool)> =
562	                if let Card::UserMsg { parts, .. } = &result[i] {
563	                    parts.iter().filter_map(|p| {
564	                        if let UserPart::ToolResult { id, content, is_error, .. } = p {
565	                            Some((id.clone(), content.clone(), *is_error))
566	                        } else { None }
567	                    }).collect()
568	                } else { vec![] };
569	
570	            if let Card::AsstMsg { parts: asst_parts, .. } = &mut result[i - 1] {
571	                for part in asst_parts.iter_mut() {
572	                    if let AsstPart::ToolCall { id, result: res, .. } = part {
573	                        if let Some((_, content, is_error)) =
574	                            tool_results.iter().find(|(rid, _, _)| rid == id)
575	                        {
576	                            *res = Some((content.clone(), *is_error));
577	                        }
578	                    }
579	                }
580	            }
581	            result.remove(i);
582	        } else {
583	            i += 1;
584	        }
585	    }
586	
587	    // Merge consecutive AsstMsg cards so the assistant name appears only once per run.
588	    let mut i = 1;
589	    while i < result.len() {
590	        if matches!(&result[i - 1], Card::AsstMsg { .. }) && matches!(&result[i], Card::AsstMsg { .. }) {
591	            if let Card::AsstMsg { parts: new_parts, .. } = result.remove(i) {
592	                if let Card::AsstMsg { parts, .. } = &mut result[i - 1] {
593	                    parts.extend(new_parts);
594	                }
595	            }
596	        } else {
597	            i += 1;
598	        }
599	    }
600	
601	    // Split each AsstMsg into a text-only AsstMsg (if any text) + a ToolRound (if any tools).
602	    let mut split: Vec<Card> = Vec::with_capacity(result.len());
603	    for card in result {
604	        match card {
605	            Card::AsstMsg { ts, parts } => {
606	                let (text_parts, tool_parts): (Vec<AsstPart>, Vec<AsstPart>) =
607	                    parts.into_iter().partition(|p| matches!(p, AsstPart::Text(_)));
608	                if !text_parts.is_empty() { split.push(Card::AsstMsg  { ts, parts: text_parts }); }
609	                if !tool_parts.is_empty() { split.push(Card::ToolRound { parts: tool_parts }); }
610	            }
611	            other => split.push(other),
612	        }
613	    }
614	    let mut result = split;
615	
616	    // Merge adjacent ToolRound cards (can arise when consecutive asst turns were all-tools).
617	    let mut i = 1;
618	    while i < result.len() {
619	        if matches!(&result[i - 1], Card::ToolRound { .. }) && matches!(&result[i], Card::ToolRound { .. }) {
620	            if let Card::ToolRound { parts: new_parts } = result.remove(i) {
621	                if let Card::ToolRound { parts } = &mut result[i - 1] {
622	                    parts.extend(new_parts);
623	                }
624	            }
625	        } else {
626	            i += 1;
627	        }
628	    }
629	
630	    result
631	}
632	
633	fn parse_user(content: &Value, tool_names: &HashMap<String, String>) -> Vec<UserPart> {
634	    let mut out = Vec::new();
635	    match content {
636	        Value::String(s) if !s.trim().is_empty() => out.push(UserPart::Text(s.clone())),
637	        Value::Array(blocks) => {
638	            for b in blocks {
639	                match b["type"].as_str() {
640	                    Some("text") => {
641	                        if let Some(t) = b["text"].as_str() {
642	                            if !t.trim().is_empty() { out.push(UserPart::Text(t.to_string())); }
643	                        }
644	                    }
645	                    Some("tool_result") => {
646	                        let id = b["tool_use_id"].as_str().unwrap_or("").to_string();
647	                        let name = tool_names.get(&id).cloned().unwrap_or_else(|| "tool".to_string());
648	                        let is_error = b["is_error"].as_bool().unwrap_or(false);
649	                        let content = match &b["content"] {
650	                            Value::String(s) => s.clone(),
651	                            Value::Array(arr) => arr.iter()
652	                                .filter(|x| x["type"].as_str() == Some("text"))
653	                                .filter_map(|x| x["text"].as_str())
654	                                .collect::<Vec<_>>().join("\n"),
655	                            _ => String::new(),
656	                        };
657	                        out.push(UserPart::ToolResult { id, name, content, is_error });
658	                    }
659	                    _ => {}
660	                }
661	            }
662	        }
663	        _ => {}
664	    }
665	    out
666	}
667	
668	fn parse_asst(content: &Value) -> Vec<AsstPart> {
669	    let mut out = Vec::new();
670	    match content {
671	        Value::String(s) if !s.trim().is_empty() => out.push(AsstPart::Text(s.clone())),
672	        Value::Array(blocks) => {
673	            for b in blocks {
674	                match b["type"].as_str() {
675	                    Some("text") => {
676	                        if let Some(t) = b["text"].as_str() {
677	                            if !t.trim().is_empty() { out.push(AsstPart::Text(t.to_string())); }
678	                        }
679	                    }
680	                    Some("tool_use") => {
681	                        out.push(AsstPart::ToolCall {
682	                            id:     b["id"].as_str().unwrap_or("").to_string(),
683	                            name:   b["name"].as_str().unwrap_or("unknown").to_string(),
684	                            input:  b["input"].clone(),
685	                            result: None,
686	                        });
687	                    }
688	                    _ => {}
689	                }
690	            }
691	        }
692	        _ => {}
693	    }
694	    out
695	}
