697	// ── Text extraction (for clipboard) ──────────────────────────────────────────
698	
699	fn card_text(card: &Card) -> String {
700	    let mut out = String::new();
701	    match card {
702	        Card::RepoLink { name, dir, branch } => {
703	            out.push_str(name); out.push('\n');
704	            out.push_str(dir);  out.push('\n');
705	            if !branch.is_empty() { out.push_str(branch); out.push('\n'); }
706	        }
707	        Card::Header { title, cwd, branch, agent, .. } => {
708	            if let Some(t) = title { out.push_str(t); out.push('\n'); }
709	            if !cwd.is_empty()    { out.push_str(cwd);               out.push('\n'); }
710	            if !branch.is_empty() { out.push_str(&format!("[{branch}]")); out.push('\n'); }
711	            if !agent.is_empty()  { out.push_str(agent); out.push('\n'); }
712	        }
713	        Card::System { content, .. } => { if !content.is_empty() { out.push_str(content); out.push('\n'); } }
714	        Card::UserMsg { parts, .. } => {
715	            for part in parts {
716	                match part {
717	                    UserPart::Text(t) => { out.push_str(t); out.push('\n'); }
718	                    UserPart::ToolResult { name, content, .. } => {
719	                        out.push_str(&format!("[Result: {name}]\n{content}\n"));
720	                    }
721	                }
722	            }
723	        }
724	        Card::AsstMsg { parts, .. } => {
725	            for part in parts {
726	                if let AsstPart::Text(t) = part { out.push_str(t); out.push('\n'); }
727	            }
728	        }
729	        Card::ToolRound { parts } => {
730	            for part in parts {
731	                if let AsstPart::ToolCall { name, input, result, .. } = part {
732	                    out.push_str(&format!("[Tool: {name}]\n"));
733	                    if let Some(obj) = input.as_object() {
734	                        for (k, v) in obj {
735	                            let val = if let Value::String(s) = v { s.clone() } else { v.to_string() };
736	                            out.push_str(&format!("{k}: {val}\n"));
737	                        }
738	                    }
739	                    if let Some((content, _)) = result {
740	                        out.push_str(&format!("[Result]\n{content}\n"));
741	                    }
742	                }
743	            }
744	        }
745	        Card::Checkpoint(cp) => {
746	            out.push_str(&format!("[Checkpoint #{}]\n", cp.number));
747	            if !cp.checkpoint_id.is_empty() { out.push_str(&format!("{}\n", cp.checkpoint_id)); }
748	            if !cp.commit_message.is_empty() { out.push_str(&cp.commit_message); out.push('\n'); }
749	            if !cp.files_touched.is_empty() {
750	                out.push_str("Files:\n");
751	                for f in &cp.files_touched { out.push_str(&format!("  {f}\n")); }
752	            }
753	        }
754	    }
755	    out
756	}
757	
758	fn tool_call_text(part: &AsstPart) -> String {
759	    let mut out = String::new();
760	    if let AsstPart::ToolCall { name, input, result, .. } = part {
761	        out.push_str(&format!("[Tool: {name}]\n"));
762	        if let Some(obj) = input.as_object() {
763	            for (k, v) in obj {
764	                let val = if let Value::String(s) = v { s.clone() } else { v.to_string() };
765	                out.push_str(&format!("{k}: {val}\n"));
766	            }
767	        }
768	        if let Some((content, _)) = result { out.push_str(&format!("[Result]\n{content}\n")); }
769	    }
770	    out
771	}
