773	fn copy_to_clipboard(text: &str) {
774	    use std::io::Write as _;
775	    use std::process::{Command, Stdio};
776	    if let Ok(mut child) = Command::new("pbcopy").stdin(Stdio::piped()).spawn() {
777	        if let Some(stdin) = child.stdin.take() {
778	            let mut stdin = stdin;
779	            let _ = stdin.write_all(text.as_bytes());
780	        }
781	        let _ = child.wait();
782	    }
783	}
