961	/// Find the git repo directory that contains `commit_sha`, trying `preferred`
962	/// first, then falling back to all registered gossamer repos.
963	fn resolve_repo_for_commit(commit_sha: &str, preferred: &str) -> Option<String> {
964	    use std::process::Command;
965	    let has_commit = |dir: &str| {
966	        Command::new("git").args(["cat-file", "-t", commit_sha])
967	            .current_dir(dir).output()
968	            .map(|o| o.status.success()).unwrap_or(false)
969	    };
970	    if !preferred.is_empty() && std::path::Path::new(preferred).exists() && has_commit(preferred) {
971	        return Some(preferred.to_string());
972	    }
973	    let Ok(conn) = crate::db::connect() else { return None; };
974	    let Ok(mut stmt) = conn.prepare("SELECT directory FROM repositories") else { return None; };
975	    let dirs: Vec<String> = stmt.query_map([], |r| r.get(0))
976	        .map(|rs| rs.flatten().collect()).unwrap_or_default();
977	    for dir in dirs {
978	        if has_commit(&dir) { return Some(dir); }
979	    }
980	    None
981	}
