1212	fn xml_root_tag(text: &str) -> &str {
1213	    let t = text.trim_start();
1214	    let inner = t.strip_prefix('<').unwrap_or(t);
1215	    let inner = inner.trim_start_matches(['!', '/']);
1216	    let end = inner.find(|c: char| c == '>' || c == ' ' || c == '\n').unwrap_or(inner.len());
1217	    let tag = &inner[..end];
1218	    if tag.is_empty() { "xml" } else { tag }
1219	}
