1221	fn strip_xml_tags(text: &str) -> String {
1222	    let mut out = String::new();
1223	    let mut in_tag = false;
1224	    for c in text.chars() {
1225	        match c {
1226	            '<' => { in_tag = true; }
1227	            '>' => { in_tag = false; }
1228	            '\n' if in_tag => {}
1229	            _ if !in_tag => out.push(c),
1230	            _ => {}
1231	        }
1232	    }
1233	    out
1234	}
