1236	fn wrap(text: &str, width: usize) -> Vec<String> {
1237	    if width < 4 { return text.lines().map(str::to_string).collect(); }
1238	    let mut out = Vec::new();
1239	    for raw_line in text.lines() {
1240	        if raw_line.is_empty() { out.push(String::new()); continue; }
1241	        let mut remaining = raw_line;
1242	        loop {
1243	            if remaining.chars().count() <= width {
1244	                out.push(remaining.to_string());
1245	                break;
1246	            }
1247	            let break_pos = remaining.chars().take(width)
1248	                .collect::<String>()
1249	                .rfind(' ')
1250	                .unwrap_or(width);
1251	            let byte_pos = remaining.char_indices().nth(break_pos)
1252	                .map(|(i, _)| i)
1253	                .unwrap_or(remaining.len());
1254	            out.push(remaining[..byte_pos].to_string());
1255	            remaining = remaining[byte_pos..].trim_start_matches(' ');
1256	        }
1257	    }
1258	    out
1259	}
