1362	/// Whether `prog` resolves to a runnable executable, either as a path
1363	/// (absolute or containing `/`) or by name via `$PATH`.
1364	fn command_exists(prog: &str) -> bool {
1365	    if prog.contains('/') {
1366	        return std::fs::metadata(prog).map(|m| !m.is_dir()).unwrap_or(false);
1367	    }
1368	    std::env::var_os("PATH").is_some_and(|paths| {
1369	        std::env::split_paths(&paths).any(|dir| {
1370	            std::fs::metadata(dir.join(prog)).map(|m| !m.is_dir()).unwrap_or(false)
1371	        })
1372	    })
1373	}
