1375	/// Find a Claude session by ID. Returns `(cwd, git_branch)` from the JSONL if found,
1376	/// so `claude --resume` can be run from the correct directory and branch is known.
1377	fn find_claude_session_cwd(session_id: &str) -> Option<(String, String)> {
1378	    use std::io::BufRead;
1379	    let home = std::env::var("HOME").ok()?;
1380	    let projects = std::path::PathBuf::from(&home).join(".claude/projects");
1381	    for dir in std::fs::read_dir(&projects).ok()?.flatten() {
1382	        let jsonl = dir.path().join(format!("{session_id}.jsonl"));
1383	        if !jsonl.exists() { continue; }
1384	        let Ok(file) = std::fs::File::open(&jsonl) else { return Some((String::new(), String::new())); };
1385	        let mut cwd = String::new();
1386	        let mut branch = String::new();
1387	        for line in std::io::BufReader::new(file).lines().flatten() {
1388	            let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
1389	            if matches!(v["type"].as_str(), Some("user") | Some("system")) {
1390	                if cwd.is_empty() {
1391	                    if let Some(c) = v["cwd"].as_str() { cwd = c.to_string(); }
1392	                }
1393	                if branch.is_empty() {
1394	                    if let Some(b) = v["gitBranch"].as_str() { branch = b.to_string(); }
1395	                }
1396	                if !cwd.is_empty() && !branch.is_empty() { break; }
1397	            }
1398	        }
1399	        return Some((cwd, branch));
1400	    }
1401	    None
1402	}
