3	//! Claude Code's JSONL has a well-known, stable shape and gets its own
4	//! bespoke, tuned parser (`parsers::claude_code` / `ingest::claude_code`).
5	//! Everything else — Codex today, whatever tomorrow — goes through this
6	//! module instead of a bespoke parser per format. Rather than deserializing
7	//! into a format-specific struct, `scan` walks each JSONL line generically
8	//! and looks for a small set of recognizable signals (a `role` field, a
9	//! `type` naming a known role synonym, text under `text`/`message`, tool
10	//! calls shaped like `{name, input|arguments}`) at the top level and one
11	//! level of nesting under `payload` (Codex's raw session log wraps
12	//! everything in `{"type": "event_msg"|"response_item", "payload": {...}}`).
13	//! A new agent format that reuses any of these conventions needs no new
14	//! code here at all; one that doesn't just falls through as unrecognized
15	//! noise rather than erroring.
16	
17	use serde_json::Value;
18	use std::collections::HashMap;
19	
20	#[derive(PartialEq, Eq, Clone, Copy)]
21	pub enum Role {
22	    User,
23	    Assistant,
24	}
25	
26	pub struct Turn {
27	    pub role: Role,
28	    pub text: String,
29	    pub timestamp: Option<String>,
30	    pub ts_ms: i64,
31	}
32	
33	#[derive(Default)]
34	pub struct ScanInfo {
35	    pub cwd: Option<String>,
36	    pub branch: Option<String>,
37	    /// Best-effort agent display name, sniffed from fields like
38	    /// `originator` ("Codex Desktop") or a per-line `agent` field
39	    /// ("codex" on compact transcripts). None when nothing was found.
40	    pub agent_hint: Option<String>,
41	    /// Cumulative output tokens, opportunistically read from a running
42	    /// `payload.info.total_token_usage.output_tokens` counter (Codex's
43	    /// `token_count` events). Last value wins since it's a running total,
44	    /// not a per-turn delta. 0 when the format doesn't report this.
45	    pub tokens_used: i64,
46	}
47	
48	const MAX_TOOL_ARG_CHARS: usize = 500;
49	const MAX_TOOL_OUTPUT_CHARS: usize = 800;
50	
51	/// Sniff whether `jsonl_bytes` looks like Claude Code's format: a top-level
52	/// `type` in Claude's known enum, with `message.role`/`message.content` for
53	/// user/assistant lines. Used only when there's no `metadata.json` to
54	/// consult (shadow branches) — checkpoint dispatch instead trusts the
55	/// `agent` field on `metadata.json`.
56	pub fn looks_like_claude_shape(jsonl_bytes: &[u8]) -> bool {
57	    let mut checked = 0;
58	    for line in jsonl_bytes.split(|&b| b == b'\n') {
59	        if line.is_empty() {
60	            continue;
61	        }
62	        let Ok(v) = serde_json::from_slice::<Value>(line) else { continue };
63	        let Some(t) = v.get("type").and_then(Value::as_str) else { continue };
64	        match t {
65	            "user" | "assistant" => {
66	                if v["message"]["role"].is_string() {
67	                    return true;
68	                }
69	            }
70	            "system" | "custom-title" | "summary" => return true,
71	            _ => {}
72	        }
73	        checked += 1;
74	        if checked >= 20 {
75	            break;
76	        }
77	    }
78	    false
79	}
80	
81	/// Walk a JSONL transcript generically, extracting session-level info and a
82	/// chronological list of user/assistant turns. Unrecognized lines (control
83	/// events, reasoning traces, session metadata, etc.) are silently skipped.
84	pub fn scan(jsonl_bytes: &[u8]) -> (ScanInfo, Vec<Turn>) {
85	    let mut info = ScanInfo::default();
86	    let mut turns: Vec<Turn> = Vec::new();
87	    // call_id -> index into `turns`, so a later `*_output` line can append
88	    // its result text to the turn that made the call.
89	    let mut pending_calls: HashMap<String, usize> = HashMap::new();
90	
91	    for line in jsonl_bytes.split(|&b| b == b'\n') {
92	        if line.is_empty() {
93	            continue;
94	        }
95	        let Ok(v) = serde_json::from_slice::<Value>(line) else { continue };
96	
97	        let timestamp = first_str(&v, &["timestamp", "ts"]).map(str::to_string);
98	        let ts_ms = timestamp
99	            .as_deref()
100	            .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
101	            .map(|dt| dt.timestamp_millis())
102	            .unwrap_or(0);
103	
104	        // Session-level info can show up on lines that carry no turn content
105	        // (e.g. Codex's `session_meta`), so this check is independent of
106	        // whether the line classifies as a turn below.
107	        collect_session_info(&v, &mut info);
108	        if let Some(n) = v.pointer("/payload/info/total_token_usage/output_tokens").and_then(Value::as_i64) {
109	            info.tokens_used = n;
110	        }
111	
112	        // Tool-call output lines don't carry a role of their own — fold them
113	        // into the call they answer, then move on.
114	        if let Some(call_id) = first_str(&v, &["call_id"]) {
115	            if let Some(&idx) = pending_calls.get(call_id) {
116	                if let Some(out) = extract_output_text(&v) {
117	                    append_result(&mut turns[idx].text, &out);
118	                }
119	                continue;
120	            }
121	        }
122	
123	        let Some((role, envelope)) = classify(&v) else { continue };
124	        let Some(text) = extract_text(envelope) else { continue };
125	        if text.trim().is_empty() {
126	            continue;
127	        }
128	
129	        // Codex's raw log reports the same user/assistant message twice —
130	        // once as a UI-facing `event_msg` notification and once as the
131	        // `response_item` conversation-history entry — so only collapse
132	        // an exact repeat of the immediately preceding turn, not any
133	        // earlier occurrence (a user genuinely repeating themselves later
134	        // in the conversation should still count as two turns).
135	        if turns.last().is_some_and(|last| last.role == role && last.text == text) {
136	            continue;
137	        }
138	
139	        turns.push(Turn { role, text, timestamp, ts_ms });
140	
141	        if let Some(call_id) = first_str(envelope, &["call_id"]) {
142	            pending_calls.insert(call_id.to_string(), turns.len() - 1);
143	        }
144	    }
145	
146	    turns.sort_by_key(|t| t.ts_ms);
147	    (info, turns)
148	}
149	
150	/// Classify a line as a User/Assistant turn, returning the sub-object whose
151	/// fields (`role`/`type`/`content`/`message`/`text`) should be used for text
152	/// extraction. Checks the line itself and one level of nesting under
153	/// `payload` (Codex's `{"type":"event_msg","payload":{...}}` wrapper).
154	fn classify(v: &Value) -> Option<(Role, &Value)> {
155	    for envelope in [v, v.get("payload").unwrap_or(&Value::Null)] {
156	        if envelope.is_null() {
157	            continue;
158	        }
159	        if let Some(role) = envelope.get("role").and_then(Value::as_str) {
160	            match role {
161	                "user" => return Some((Role::User, envelope)),
162	                "assistant" => return Some((Role::Assistant, envelope)),
163	                _ => continue, // developer/system/tool — not a turn
164	            }
165	        }
166	        if let Some(t) = envelope.get("type").and_then(Value::as_str) {
167	            match t {
168	                "user" | "user_message" => return Some((Role::User, envelope)),
169	                "assistant" | "agent_message" | "agent_reasoning" => {
170	                    return Some((Role::Assistant, envelope));
171	                }
172	                "function_call" | "custom_tool_call" | "tool_use" => {
173	                    return Some((Role::Assistant, envelope));
174	                }
175	                _ => {}
176	            }
177	        }
178	    }
179	    None
180	}
181	
182	/// Pull display text out of a classified envelope: plain `message`/`text`
183	/// fields, a `content` string/array, or (for tool-call envelopes) a
184	/// synthesized `[Tool: name] args` line.
185	fn extract_text(envelope: &Value) -> Option<String> {
186	    if envelope.get("name").and_then(Value::as_str).is_some() {
187	        return Some(format_tool_call(envelope));
188	    }
189	
190	    if let Some(s) = first_str(envelope, &["message", "text"]) {
191	        return Some(s.to_string());
192	    }
193	
194	    match envelope.get("content") {
195	        Some(Value::String(s)) => Some(s.clone()),
196	        Some(Value::Array(blocks)) => {
197	            let parts: Vec<String> = blocks.iter().filter_map(extract_block_text).collect();
198	            if parts.is_empty() { None } else { Some(parts.join("\n")) }
199	        }
200	        _ => None,
201	    }
202	}
203	
204	/// Extract text from a single content/output block. Blocks are treated as
205	/// text-bearing purely by the presence of a `.text` field, not by their
206	/// declared `type` tag — Codex uses `"input_text"` where Claude uses
207	/// `"text"`, so keying off the tag name would miss it.
208	fn extract_block_text(block: &Value) -> Option<String> {
209	    if let Value::String(s) = block {
210	        return Some(s.clone());
211	    }
212	    if let Some(s) = block.get("text").and_then(Value::as_str) {
213	        return Some(s.to_string());
214	    }
215	    if block.get("name").and_then(Value::as_str).is_some() {
216	        return Some(format_tool_call(block));
217	    }
218	    None
219	}
220	
221	/// Format a tool-call-shaped object (`{name, arguments|input, [result|output]}`)
222	/// as a single searchable line, folding in an inline result if present
223	/// (compact-transcript blocks embed the result on the same object; Codex's
224	/// raw log instead reports it on a later, `call_id`-correlated line — see
225	/// `pending_calls` in `scan`).
226	fn format_tool_call(envelope: &Value) -> String {
227	    let name = envelope.get("name").and_then(Value::as_str).unwrap_or("tool");
228	    let args = first_str(envelope, &["arguments", "input"]).unwrap_or("");
229	    let mut text = format!("[Tool: {name}] {}", truncate(args, MAX_TOOL_ARG_CHARS));
230	    if let Some(out) = extract_output_text(envelope) {
231	        append_result(&mut text, &out);
232	    }
233	    text
234	}
235	
236	fn append_result(text: &mut String, output: &str) {
237	    if output.trim().is_empty() {
238	        return;
239	    }
240	    text.push_str("\n→ ");
241	    text.push_str(&truncate(output, MAX_TOOL_OUTPUT_CHARS));
242	}
243	
244	/// Extract result/output text from a tool-call-output line or an inline
245	/// `result`/`output` field, checking the line itself and one level of
246	/// nesting under `payload`. Handles a plain string, an array of blocks, or
247	/// an object with its own `output` string (Codex compact transcript's
248	/// `{"output": "...", "status": "success"}`).
249	fn extract_output_text(v: &Value) -> Option<String> {
250	    for envelope in [v, v.get("payload").unwrap_or(&Value::Null)] {
251	        if envelope.is_null() {
252	            continue;
253	        }
254	        let Some(out) = envelope.get("output").or_else(|| envelope.get("result")) else { continue };
255	        match out {
256	            Value::String(s) => return Some(s.clone()),
257	            Value::Array(blocks) => {
258	                let parts: Vec<String> = blocks.iter().filter_map(extract_block_text).collect();
259	                if !parts.is_empty() {
260	                    return Some(parts.join("\n"));
261	                }
262	            }
263	            Value::Object(_) => {
264	                if let Some(s) = out.get("output").and_then(Value::as_str) {
265	                    return Some(s.to_string());
266	                }
267	            }
268	            _ => {}
269	        }
270	    }
271	    None
272	}
273	
274	fn collect_session_info(v: &Value, info: &mut ScanInfo) {
275	    if info.cwd.is_none() {
276	        if let Some(c) = first_str(v, &["cwd"]) {
277	            info.cwd = Some(c.to_string());
278	        }
279	    }
280	    if info.branch.is_none() {
281	        if let Some(b) = first_str(v, &["gitBranch", "branch"]) {
282	            info.branch = Some(b.to_string());
283	        }
284	    }
285	    if info.agent_hint.is_none() {
286	        if let Some(a) = first_str(v, &["agent"]) {
287	            info.agent_hint = Some(a.to_string());
288	        } else if let Some(o) = first_str(v, &["originator"]) {
289	            info.agent_hint = Some(normalize_originator(o));
290	        }
291	    }
292	}
293	
294	/// "Codex Desktop" / "Codex CLI" -> "Codex"; anything else passed through.
295	fn normalize_originator(originator: &str) -> String {
296	    originator
297	        .split_whitespace()
298	        .next()
299	        .unwrap_or(originator)
300	        .to_string()
301	}
302	
303	/// Look for the first of `keys` as a string field, checking the value
304	/// itself and one level of nesting under `payload`.
305	fn first_str<'a>(v: &'a Value, keys: &[&str]) -> Option<&'a str> {
306	    for envelope in [v, v.get("payload").unwrap_or(&Value::Null)] {
307	        for key in keys {
308	            if let Some(s) = envelope.get(*key).and_then(Value::as_str) {
309	                if !s.is_empty() {
310	                    return Some(s);
311	                }
312	            }
313	        }
314	    }
315	    None
316	}
317	
318	/// True when `text` opens with an XML-ish wrapper tag (`<environment_context>`,
319	/// `<command-message>`, `<recommended_plugins>`, ...) rather than actual user
320	/// intent. Different agents invent their own tag names for this kind of
321	/// injected context/metadata, so this matches on the generic shape of an
322	/// opening tag rather than a per-agent name list.
323	pub fn is_wrapper_prompt(text: &str) -> bool {
324	    let first_line = text.lines().next().unwrap_or("").trim_start();
325	    let Some(rest) = first_line.strip_prefix('<') else { return false };
326	    let tag: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '-' || *c == '_').collect();
327	    !tag.is_empty() && rest[tag.len()..].starts_with(|c: char| c == '>' || c.is_whitespace())
328	}
329	
330	fn truncate(s: &str, max_chars: usize) -> String {
331	    if s.chars().count() <= max_chars {
332	        return s.to_string();
333	    }
334	    let truncated: String = s.chars().take(max_chars).collect();
335	    format!("{truncated}…")
336	}
337	
338	#[cfg(test)]
339	mod tests {
340	    use super::*;
341	
342	    #[test]
343	    fn extracts_codex_user_and_assistant_messages() {
344	        let jsonl = r#"{"timestamp":"2026-07-14T15:39:16.517Z","type":"event_msg","payload":{"type":"user_message","message":"hello there"}}
345	{"timestamp":"2026-07-14T15:39:18.938Z","type":"event_msg","payload":{"type":"agent_message","message":"hi back"}}"#;
346	        let (_, turns) = scan(jsonl.as_bytes());
347	        assert_eq!(turns.len(), 2);
348	        assert!(matches!(turns[0].role, Role::User));
349	        assert_eq!(turns[0].text, "hello there");
350	        assert!(matches!(turns[1].role, Role::Assistant));
351	        assert_eq!(turns[1].text, "hi back");
352	    }
353	
354	    #[test]
355	    fn correlates_tool_call_with_its_output() {
356	        let jsonl = r#"{"timestamp":"2026-07-14T15:39:22.5Z","type":"response_item","payload":{"type":"function_call","name":"exec","arguments":"{\"cmd\":\"pwd\"}","call_id":"c1"}}
357	{"timestamp":"2026-07-14T15:39:23.0Z","type":"response_item","payload":{"type":"function_call_output","call_id":"c1","output":[{"type":"input_text","text":"/repo"}]}}"#;
358	        let (_, turns) = scan(jsonl.as_bytes());
359	        assert_eq!(turns.len(), 1);
360	        assert!(turns[0].text.contains("[Tool: exec]"));
361	        assert!(turns[0].text.contains("pwd"));
362	        assert!(turns[0].text.contains("→ /repo"));
363	    }
364	
365	    #[test]
366	    fn collapses_duplicate_user_message_across_envelopes() {
367	        // Codex logs the same user message once as a `response_item` and once
368	        // as an `event_msg` notification — real shape seen in ~/p/entire-graph.
369	        let jsonl = r#"{"timestamp":"2026-07-14T15:39:16.517Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":"hello there"}]}}
370	{"timestamp":"2026-07-14T15:39:16.518Z","type":"event_msg","payload":{"type":"user_message","message":"hello there"}}"#;
371	        let (_, turns) = scan(jsonl.as_bytes());
372	        assert_eq!(turns.len(), 1);
373	        assert_eq!(turns[0].text, "hello there");
374	    }
375	
376	    #[test]
377	    fn skips_developer_and_control_events() {
378	        let jsonl = r#"{"type":"response_item","payload":{"type":"message","role":"developer","content":[{"type":"input_text","text":"system prompt"}]}}
379	{"type":"event_msg","payload":{"type":"task_started","turn_id":"t1"}}
380	{"type":"session_meta","payload":{"cwd":"/repo","originator":"Codex Desktop"}}"#;
381	        let (info, turns) = scan(jsonl.as_bytes());
382	        assert!(turns.is_empty());
383	        assert_eq!(info.cwd.as_deref(), Some("/repo"));
384	        assert_eq!(info.agent_hint.as_deref(), Some("Codex"));
385	    }
386	
387	    #[test]
388	    fn wrapper_prompt_detection_is_agent_agnostic() {
389	        // Claude's own wrapper tags...
390	        assert!(is_wrapper_prompt("<command-message>foo</command-message>"));
391	        // ...and Codex's differently-named ones (real shape seen in
392	        // ~/p/entire-graph) are both recognized by tag shape, not by name.
393	        assert!(is_wrapper_prompt("<environment_context>\n  <cwd>/repo</cwd>\n</environment_context>"));
394	        assert!(is_wrapper_prompt("<recommended_plugins>\nHere is a list...\n</recommended_plugins>"));
395	        assert!(!is_wrapper_prompt("Continue the work from the completed CLI handoff."));
396	    }
397	
398	    #[test]
399	    fn claude_shape_sniff() {
400	        let claude = br#"{"type":"user","message":{"role":"user","content":"hi"}}"#;
401	        assert!(looks_like_claude_shape(claude));
402	        let codex = br#"{"type":"event_msg","payload":{"type":"user_message","message":"hi"}}"#;
